mapper.select:
select cat_id, archive_no, cat_name, qr_code from cat_profile
where del_flag = '0' and cat_id in
#{id}



    AND archive_no like concat('%', #{archiveNo}, '%')
    AND cat_name like concat('%', #{catName}, '%')
    AND alias like concat('%', #{alias}, '%')
    AND breed = #{breed}
    AND sex = #{sex}
    AND age_estimate = #{ageEstimate}

    AND timestampdiff(month, birth_date, curdate()) >= #{ageMinMonths}
    AND timestampdiff(month, birth_date, curdate()) <= #{ageMaxMonths}
    AND birth_date is null
    AND weight = #{weight}
    AND personality = #{personality}
    AND source = #{source}
    AND capture_date = #{captureDate}
    AND capture_point like concat('%', #{capturePoint}, '%')
    AND neutered = #{neutered}
    AND dewormed = #{dewormed}
    AND vaccinated = #{vaccinated}
    AND feature like concat('%', #{feature}, '%')



            AND (
                cat_name like concat('%', #{kw}, '%')
                or archive_no like concat('%', #{kw}, '%')
                or ifnull(alias, '') like concat('%', #{kw}, '%')
                or ifnull(feature, '') like concat('%', #{kw}, '%')
                or ifnull(breed, '') like concat('%', #{kw}, '%')
                or ifnull(age_estimate, '') like concat('%', #{kw}, '%')
                or (case sex when '0' then '公' when '1' then '母' when '2' then '未知' else '' end)
                   like concat('%', #{kw}, '%')
            )


    AND status = #{status}
    AND base_id = #{baseId}
    AND ward_id = #{wardId}

    AND ward_id is null




                AND ward_id IN
                #{wid}

            AND 1 = 0


    AND owner_base_id = #{ownerBaseId}
    AND hospital_name = #{hospitalName}
    AND archived = #{archived}



        AND cat_id IN (
            SELECT cat_id FROM cat_profile_tag WHERE tag_id IN
            #{tagId}
            GROUP BY cat_id HAVING COUNT(DISTINCT tag_id) = #{tagSize}
        )

    AND del_flag = '0'

order by cat_id desc
